    option.textContent = preset.label;
    firmwareSelect.appendChild(option);
  }
  const installBtn = document.createElement('button');
  installBtn.type = 'button';
  installBtn.textContent = 'Install firmware';
  installBtn.style.cssText = primaryBtnStyle;
  installBtn.disabled = !presets.length;
  firmwareRow.append(firmwareSelect, installBtn);
  firmwareSection.appendChild(firmwareRow);
  if (!presets.length) {
    const noPresets = document.createElement('p');
    noPresets.textContent = 'No firmware published yet for this chip.';
    noPresets.style.cssText = 'margin:8px 0 0;font-size:11px;color:var(--text-muted);';
    firmwareSection.appendChild(noPresets);
  }
  const progressEl = document.createElement('div');
  progressEl.style.cssText = 'margin:8px 0 0;font-size:11px;color:var(--text-muted);';
  firmwareSection.appendChild(progressEl);
  container.appendChild(firmwareSection);

  // Shown only once the board's own console confirmed it's actually
  // running -- this is where the "fixed hardware modules" live; for now
  // that's just Digital I/O (see the module's own children), CAN/WiFi etc.
  // are future, separate submodules, not this one's job.
  const programSection = document.createElement('div');
  programSection.style.cssText = sectionStyle + 'display:none;';
  const programLabel = document.createElement('div');
  programLabel.textContent = 'DIGITAL I/O';
  programLabel.style.cssText = labelStyle;
  programSection.appendChild(programLabel);
  const programStatus = document.createElement('p');
  programStatus.style.cssText = 'margin:0 0 8px;font-size:11px;color:var(--text-muted);';
  programSection.appendChild(programStatus);
  const sendBtn = document.createElement('button');
  sendBtn.type = 'button';
  sendBtn.textContent = 'Save changes to device';
  sendBtn.style.cssText = btnStyle;
  programSection.appendChild(sendBtn);

  // Live hardware override -- separate from "Save changes to device" above,
  // which only ever declares pins (see buildMinimalDesign's own doc on why
  // it can't yet compile real wiring). This talks straight to ioWrite() on
  // the board (see esp32_logic's `io <gpio> <0|1>` serial command), the same
  // direct-pin override its own browser circuit editor already does over
  // WebSocket -- bypasses circuit logic entirely, on both ends.
  const pinsLabel = document.createElement('div');
  pinsLabel.textContent = 'LIVE PINS';
  pinsLabel.style.cssText = labelStyle + 'margin-top:14px;';
  programSection.appendChild(pinsLabel);
  const pinsListEl = document.createElement('div');
  pinsListEl.style.cssText = 'display:flex;flex-direction:column;gap:6px;';
  programSection.appendChild(pinsListEl);
  container.appendChild(programSection);

  function updateProgramSection() {
    const childCount = block.children ? block.children.blocks.size : 0;
    // Reads block.props directly rather than the `props` shorthand --
    // that's a one-time snapshot taken when the dialog opened, so it would
    // still show the *previous* lastSentSnapshot right after a successful
    // save this same session (helpers.setProp mutates the live block, not
    // this closure's own copy of it).
    const lastSent = (block.props.find((p) => p.name === 'lastSentSnapshot') || {}).value || '';
    const dirty = childCount && childSnapshot() !== lastSent;
    programStatus.textContent = !childCount
      ? 'No Digital I/O blocks inside this ' + (block.name || 'ESP32 DevKit') + ' yet -- enter it to add some.'
      : dirty ? 'Circuit changed -- not yet saved to the device.' : 'Circuit matches what is on the device.';
    sendBtn.disabled = !childCount;
  }
  updateProgramSection();

  // One row per Digital I/O child with a real pin set -- the exact same
  // filter buildMinimalDesign uses, so "what Save would send" and "what
  // Live Pins shows" never disagree about which children count.
  function pinChildren() {
    const children = block.children ? Array.from(block.children.blocks.values()) : [];
    return children
      .filter((c) => (c.props || []).find((p) => p.name === 'noditronKind')?.value === 'digital-io')
      .map((c) => {
        const pin = (c.props || []).find((p) => p.name === 'pin')?.value;
        const direction = (c.props || []).find((p) => p.name === 'direction')?.value === 'output' ? 'output' : 'input';
        const valueProp = (c.props || []).find((p) => p.name === 'value');
        return { child: c, pin, direction, valueProp };
      })
      .filter((entry) => entry.pin !== null && entry.pin !== undefined && entry.pin !== '');
  }

  const pinRows = new Map(); // childId -> { row, dot, label, btn }

  async function setChildValue(entry, on) {
    if (entry.valueProp) entry.valueProp.value = on ? 1 : 0;
    const bd = await import('/nodigraph/src/model/BlockDescription.js');
    entry.child.description = bd.serializeBlockDescription(entry.child);
    helpers.refresh();
  }

  function renderPinsList() {
    const entries = pinChildren();
    const seen = new Set();
    for (const entry of entries) {
      seen.add(entry.child.id);
      let ui = pinRows.get(entry.child.id);
      if (!ui) {
        const row = document.createElement('div');
        row.style.cssText = 'display:flex;align-items:center;gap:8px;font-size:12px;';
        const dot = document.createElement('span');
        dot.style.cssText = 'width:10px;height:10px;border-radius:50%;flex:none;border:2px solid var(--border);box-sizing:border-box;';
        const label = document.createElement('span');
        label.style.cssText = 'flex:1;color:var(--text-secondary);';
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.style.cssText = btnStyle + 'padding:3px 10px;font-size:11px;';
        row.append(dot, label, btn);
        pinsListEl.appendChild(row);
        ui = { row, dot, label, btn };
        pinRows.set(entry.child.id, ui);
      }
      const on = Number(entry.valueProp && entry.valueProp.value) >= 1;
      ui.label.textContent = 'GPIO' + entry.pin + ' · ' + entry.direction.toUpperCase() + ' · ' + (entry.child.name || 'Digital I/O');
      ui.dot.style.background = on ? '#3ecf5d' : 'transparent';
      ui.dot.style.borderColor = on ? '#3ecf5d' : 'var(--border)';
      if (entry.direction === 'output') {
        ui.btn.style.display = '';
        ui.btn.textContent = on ? 'Set LOW' : 'Set HIGH';
        ui.btn.onclick = async () => {
          const next = !on;
          ui.btn.disabled = true;
          try {
            await helpers.console.setPin(entry.pin, next);
            await setChildValue(entry, next);
            renderPinsList();
          } catch (err) {
            log('Set GPIO' + entry.pin + ' failed: ' + err.message);
          } finally {
            ui.btn.disabled = false;
          }
        };
      } else {
        ui.btn.style.display = 'none';
        ui.btn.onclick = null;
      }
    }
    for (const [childId, ui] of pinRows) {
      if (!seen.has(childId)) {
        ui.row.remove();
        pinRows.delete(childId);
      }
    }
    pinsLabel.style.display = entries.length ? '' : 'none';
  }
  renderPinsList();

  // Reflects hardware-side changes back into the UI (an input pin toggled
  // by whatever it's wired to on the board, or another client's own live
  // control) -- not just this dialog's own writes. Stops itself once the
  // dialog closes (container.isConnected goes false) or the device stops
  // answering; no explicit "dialog closed" hook exists to unsubscribe from
  // otherwise (see dialogSystem.js's close(), which just clears innerHTML).
  //
  // A self-scheduling setTimeout loop, not setInterval -- the next poll is
  // only queued once the current one's round trip (readPins is itself
  // async) actually finishes, so a slow reply can never stack a second
  // request behind the first on the same serial link. The gap between
  // polls is what was previously a fixed 800ms interval; shrunk to 150ms
  // since the round trip itself is normally well under that (a few dozen
  // bytes at 115200 baud) -- most of the old perceived latency was just
  // this gap, not the device being slow to answer.
  let pinsPollActive = false;
  function startPinsPoll() {
    if (pinsPollActive) return;
    pinsPollActive = true;
    (async function pollLoop() {
      while (pinsPollActive) {
        if (!container.isConnected || programSection.style.display === 'none') {
          pinsPollActive = false;
          break;
        }
        try {
          const livePins = await helpers.console.readPins({ timeoutMs: 1500 });
          const byGpio = new Map(livePins.map((p) => [p.gpio, p]));
          for (const entry of pinChildren()) {
            const live = byGpio.get(Number(entry.pin));
            if (live && entry.valueProp) entry.valueProp.value = live.state ? 1 : 0;
          }
          renderPinsList();
        } catch (_) {
          // A missed poll just leaves the UI showing the last known state --
          // no reason to log every dropped byte on a link that otherwise works.
        }
        await new Promise((resolve) => setTimeout(resolve, 150));
      }
    })();
  }

  // A truly blank chip also needs its own bootloader/partition table, not
  // just the app image "Install firmware" above assumes is already there
  // (the ordinary case -- factory-fresh or previously-flashed boards both
  // already have one). Collapsed since most people never need it.
  const advanced = document.createElement('details');
  advanced.style.cssText = 'margin:0 0 12px;';
  const summary = document.createElement('summary');
  summary.textContent = 'Advanced: flash files manually';
  summary.style.cssText = 'cursor:pointer;font-size:11px;color:var(--text-muted);margin-bottom:8px;';
  advanced.appendChild(summary);
  const rows = document.createElement('div');
  advanced.appendChild(rows);
  const addRowBtn = document.createElement('button');
  addRowBtn.type = 'button';
  addRowBtn.textContent = '+ Add file';
  addRowBtn.style.cssText = btnStyle;
  advanced.appendChild(addRowBtn);
  const eraseRow = document.createElement('label');
  eraseRow.style.cssText = 'display:flex;align-items:center;gap:8px;margin:12px 0;cursor:pointer;font-size:12px;';
  const eraseCheckbox = document.createElement('input');
  eraseCheckbox.type = 'checkbox';
  eraseCheckbox.checked = true;
  eraseRow.append(eraseCheckbox, document.createTextNode('Erase flash before writing (recommended for a blank board)'));
  advanced.appendChild(eraseRow);
  const flashBtn = document.createElement('button');
  flashBtn.type = 'button';
  flashBtn.textContent = 'Flash';
  flashBtn.style.cssText = btnStyle;
  advanced.appendChild(flashBtn);
  container.appendChild(advanced);

  const logEl = document.createElement('pre');
  logEl.style.cssText = 'margin:0;padding:8px;border:1px solid var(--border);border-radius:6px;background:var(--bg-well);color:var(--text-secondary);font-family:ui-monospace,Consolas,monospace;font-size:11px;white-space:pre-wrap;word-break:break-word;max-height:140px;overflow:auto;';
  logEl.textContent = String(props.connectionState || 'disconnected');
  container.appendChild(logEl);
  function log(line) {
    logEl.textContent += '\n' + line;
    logEl.scrollTop = logEl.scrollHeight;
  }

  let bootloaderOffset = null;

  function showRunning() {
    firmwareSection.style.display = 'none';
    programSection.style.display = '';
    updateProgramSection();
    renderPinsList();
    startPinsPoll();
  }

  function showNeedsFirmware() {
    programSection.style.display = 'none';
    firmwareSection.style.display = '';
  }

  // The one place that decides what's actually on the other end of the
  // port: try the console's own 'ping' first (harmless if it's already
  // running -- just a status line back), and only reset into the ROM
  // bootloader if nothing answers. Reused after Connect, and again after
  // Install firmware once the board's had a moment to boot into it.
  async function afterPortOpen() {
    statusEl.textContent = 'Connected -- checking for firmware...';
    try {
      const info = await helpers.console.identify({ timeoutMs: 1500 });
      if (info.verified) {
        statusEl.textContent = 'Logic Module v' + info.version + ' running.';
        log('ping: v' + info.version + ' build ' + info.build + ', heap=' + info.heap + '.');
        helpers.setProp('connectionState', 'connected:running');
        showRunning();
        return;
      }
    } catch (err) {
      log('Console check failed: ' + err.message);
    }
    try {
      const detected = await helpers.serial.detectChip(log);
      bootloaderOffset = detected.bootloaderOffset;
      statusEl.textContent = detected.chipName + ' detected -- no firmware running yet.';
      log('Detected ' + detected.chipName + ' (bootloader @ 0x' + detected.bootloaderOffset.toString(16) + ').');
      helpers.setProp('connectionState', 'connected:needs-firmware:' + detected.chipName);
      showNeedsFirmware();
    } catch (err) {
      statusEl.textContent = 'Connected, but could not identify the board.';
      log('Chip detect failed: ' + err.message);
      helpers.setProp('connectionState', 'connected:unknown');
    }
  }

  const existing = helpers.serial.getSession();
  if (existing) {
    disconnectBtn.disabled = false;
    connectBtn.disabled = true;
    afterPortOpen();
  } else {
    statusEl.textContent = 'Not connected.';
  }

  connectBtn.addEventListener('click', async () => {
    connectBtn.disabled = true;
    try {
      await helpers.serial.connect(log);
      log('Serial port opened.');
      disconnectBtn.disabled = false;
      await afterPortOpen();
    } catch (err) {
      statusEl.textContent = 'Connect failed: ' + err.message;
      connectBtn.disabled = false;
    }
  });

  disconnectBtn.addEventListener('click', async () => {
    helpers.console.close();
    await helpers.serial.disconnect();
    statusEl.textContent = 'Disconnected.';
    connectBtn.disabled = false;
    disconnectBtn.disabled = true;
    firmwareSection.style.display = 'none';
    programSection.style.display = 'none';
    helpers.setProp('connectionState', 'disconnected');
  });

  installBtn.addEventListener('click', async () => {
    const preset = presets.find((p) => p.id === firmwareSelect.value);
    if (!preset) return;
    installBtn.disabled = true;
    const original = installBtn.textContent;
    installBtn.textContent = 'Installing...';
    try {
      const files = await helpers.serial.fetchPresetParts(preset);
      log('Fetched ' + preset.label + ' (' + files.map((f) => f.name).join(', ') + ').');
      // Every part of the preset, written together in one writeFlash call --
      // never just the app image alone. A board that only ever gets its app
      // partition rewritten keeps whatever bootloader/partition table it
      // already has, which is fine right up until one doesn't have either
      // (a genuinely blank or fully erased chip) -- then the ROM loops
      // "invalid header: 0xffffffff" forever with nothing to hand off to.
      // Rewriting an unchanged bootloader/partition table on a board that
      // already had one is a harmless no-op, so always including them here
      // costs nothing on the common case and fixes the blank-chip one.
      await helpers.serial.flash(
        files,
        false,
        (fileIndex, written, total) => {
          progressEl.textContent = 'File ' + (fileIndex + 1) + '/' + files.length + ': ' + Math.round((written / total) * 100) + '%';
        },
        log,
      );
      progressEl.textContent = '';
      statusEl.textContent = 'Flashed -- waiting for the board to boot...';
      await new Promise((resolve) => setTimeout(resolve, 2000));
      await afterPortOpen();
    } catch (err) {
      log('Install failed: ' + err.message);
    } finally {
      installBtn.disabled = false;
      installBtn.textContent = original;
    }
  });

  sendBtn.addEventListener('click', async () => {
    sendBtn.disabled = true;
    const original = sendBtn.textContent;
    sendBtn.textContent = 'Saving...';
    try {
      const children = block.children ? Array.from(block.children.blocks.values()) : [];
      const design = helpers.console.buildMinimalDesign(children);
      if (!design.blocks.length) {
        log('Nothing to send -- add a Digital I/O block inside this ESP32 DevKit with a real pin set first.');
      } else {
        await helpers.console.sendDesign(design);
        helpers.setProp('lastSentSnapshot', childSnapshot());
        log('Saved ' + design.blocks.length + ' pin(s) to the device. It applies immediately and survives reboot.');
        updateProgramSection();
      }
    } catch (err) {
      log('Save failed: ' + err.message);
    } finally {
      sendBtn.disabled = false;
      sendBtn.textContent = original;
    }
  });

  function addFileRow() {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px;margin-bottom:6px;';
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = '.bin';
    fileInput.style.cssText = 'flex:1;font-size:11px;min-width:0;';
    const addrInput = document.createElement('input');
    addrInput.type = 'text';
    addrInput.style.cssText = 'width:90px;flex:none;padding:4px 6px;background:none;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);font-size:12px;font-family:ui-monospace,monospace;box-sizing:border-box;';
    addrInput.value = '0x10000';
    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.textContent = String.fromCharCode(215);
    removeBtn.style.cssText = 'width:22px;height:22px;flex:none;padding:0;border:1px solid var(--border);border-radius:6px;background:none;color:var(--text-muted);cursor:pointer;';
    removeBtn.addEventListener('click', () => row.remove());
    fileInput.addEventListener('change', () => {
      const f = fileInput.files[0];
      if (f) addrInput.value = '0x' + helpers.serial.guessAddress(f.name, bootloaderOffset).toString(16);
    });
    row.append(fileInput, addrInput, removeBtn);
    rows.appendChild(row);
  }
  addFileRow();
  addRowBtn.addEventListener('click', () => addFileRow());

  flashBtn.addEventListener('click', async () => {
    const files = [];
    for (const row of rows.children) {
      const addrInput = row.querySelector('input[type=text]');
      const address = parseInt(addrInput.value, 16) || 0;
      const fileInput = row.querySelector('input[type=file]');
      const file = fileInput && fileInput.files[0];
      if (!file) continue;
      files.push({ name: file.name, file, address });
    }
    if (!files.length) { log('Pick at least one .bin file first.'); return; }
    flashBtn.disabled = true;
    try {
      await helpers.serial.flash(
        files,
        eraseCheckbox.checked,
        (fileIndex, written, total) => {
          progressEl.textContent = 'File ' + (fileIndex + 1) + ': ' + Math.round((written / total) * 100) + '%';
        },
        log,
      );
      statusEl.textContent = 'Flashed -- waiting for the board to boot...';
      await new Promise((resolve) => setTimeout(resolve, 2000));
      await afterPortOpen();
    } catch (err) {
      log('Flash failed: ' + err.message);
    } finally {
      flashBtn.disabled = false;
    }
  });
}
